module largest_non_square (\n    input clk,\n    input rst_n,\n    input start,\n    input [15:0] arr_0, arr_1, arr_2, arr_3, arr_4, arr_5, arr_6, arr_7,\n    output reg [15:0] result,\n    output reg done\n);\n\n    localparam [2:0] IDLE    = 3'b000;\n    localparam [2:0] INIT    = 3'b001;\n    localparam [2:0] CHECK   = 3'b010;\n    localparam [2:0] UPDATE  = 3'b011;\n    localparam [2:0] NEXT    = 3'b100;\n    localparam [2:0] DONE_STATE = 3'b101;\n\n    reg [2:0] state;\n    reg [2:0] current_index;\n    reg [15:0] max_val;\n    reg [15:0] current_val;\n    reg [8:0] y;\n\n    wire [17:0] y_squared = y * y;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 16'd0;\n            max_val <= 16'sd32768;\n            current_index <= 3'd0;\n            current_val <= 16'd0;\n            y <= 9'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) state <= INIT;\n                end\n                \n                INIT: begin\n                    max_val <= 16'sd32768;\n                    current_index <= 3'd0;\n                    current_val <= arr_0;\n                    y <= 9'd0;\n                    state <= CHECK;\n                end\n                \n                CHECK: begin\n                    if (current_val[15]) begin  // Negative\n                        state <= UPDATE;\n                    end else begin\n                        if (y_squared == current_val) begin\n                            state <= NEXT;\n                        end else if (y_squared > current_val) begin\n                            state <= UPDATE;\n                        end else begin\n                            y <= y + 9'd1;\n                        end\n                    end\n                end\n                \n                UPDATE: begin\n                    if ($signed(current_val) > $signed(max_val)) begin\n                        max_val <= current_val;\n                    end\n                    state <= NEXT;\n                end\n                \n                NEXT: begin\n                    if (current_index < 3'd7) begin\n                        current_index <= current_index + 3'd1;\n                        case (current_index + 3'd1)\n                            3'd0: current_val <= arr_0;\n                            3'd1: current_val <= arr_1;\n                            3'd2: current_val <= arr_2;\n                            3'd3: current_val <= arr_3;\n                            3'd4: current_val <= arr_4;\n                            3'd5: current_val <= arr_5;\n                            3'd6: current_val <= arr_6;\n                            3'd7: current_val <= arr_7;\n                        endcase\n                        y <= 9'd0;\n                        state <= CHECK;\n                    end else begin\n                        state <= DONE_STATE;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    result <= max_val;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule